use super::url::Url;

pub(super) fn parse_url(input: String) -> Url {
    let (scheme, remainder, has_authority_section) = match input.find("://") {
        Some(index) => (
            input[..index].to_string(),
            &input[index + 3..],
            true,
        ),
        None => (String::new(), input.as_str(), false),
    };

    let (before_fragment, fragment) = split_component(remainder, '#');
    let (before_query, query) = split_component(before_fragment, '?');

    if has_authority_section {
        let (authority_raw, path) = split_authority_and_path(before_query);
        let (userinfo, host, port) = parse_authority(authority_raw);
        Url::from_parts(scheme, userinfo, host, port, path, query, fragment)
    } else {
        Url::from_parts(
            String::new(),
            String::new(),
            String::new(),
            -1,
            before_query.to_string(),
            query,
            fragment,
        )
    }
}

fn split_component(input: &str, delimiter: char) -> (&str, String) {
    match input.find(delimiter) {
        Some(index) => (&input[..index], input[index + delimiter.len_utf8()..].to_string()),
        None => (input, String::new()),
    }
}

fn split_authority_and_path(input: &str) -> (&str, String) {
    match input.find('/') {
        Some(index) => (&input[..index], input[index..].to_string()),
        None => (input, String::new()),
    }
}

fn parse_authority(input: &str) -> (String, String, i32) {
    let (userinfo, host_port) = match input.find('@') {
        Some(index) => (input[..index].to_string(), &input[index + 1..]),
        None => (String::new(), input),
    };

    let (host, port) = match host_port.find(':') {
        Some(index) => (
            host_port[..index].to_string(),
            parse_port(&host_port[index + 1..]),
        ),
        None => (host_port.to_string(), -1),
    };

    (userinfo, host, port)
}

fn parse_port(input: &str) -> i32 {
    let digits_len = input
        .bytes()
        .take_while(|byte| byte.is_ascii_digit())
        .count();

    if digits_len == 0 {
        return -1;
    }

    let mut value: u32 = 0;
    for byte in input.bytes().take(digits_len) {
        value = match value.checked_mul(10) {
            Some(next) => next + u32::from(byte - b'0'),
            None => return -1,
        };

        if value > 65_535 {
            return -1;
        }
    }

    value as i32
}

